// Streaming-multiprocessor count of the device this process runs on, queried once and cached.
// Launch geometry that deliberately fills one resident wave reads the count from here instead of
// transcribing a per-part literal. The product runs one resident model on one device, so a single
// cached query is the whole device set. Declared target: NVIDIA L20 (AD102, sm_89, 92 SMs).
int device_sm_count();

} // namespace

int device_sm_count() {
    static const int count = [] {
        int current = 0;
        if (cudaGetDevice(&current) != cudaSuccess) {
            throw std::runtime_error(
                cuda_error_message("cudaGetDevice failed", cudaGetLastError()));
        }
        cudaDeviceProp props{};
        const cudaError_t err = cudaGetDeviceProperties(&props, current);
        if (err != cudaSuccess) {
            throw std::runtime_error(cuda_error_message("cudaGetDeviceProperties failed", err));
        }
        return props.multiProcessorCount;
    }();
    return count;
}

